package org.botai.back.b2b;

import java.io.*;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.botai.back.common.*;
import org.botai.back.grading.*;
import org.botai.back.media.*;
import org.botai.back.media.port.ObjectStorage;
import org.botai.back.security.CurrentActor;
import org.botai.back.user.Role;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.multipart.MultipartFile;
import tools.jackson.databind.JsonNode;

/** Operator-only persisted views over the real immutable submission pipeline. */
@Service
@RequiredArgsConstructor
public class LocalDemoService {
    private final B2bConfig config;private final SubmissionOrigins origins;private final CurrentActor actors;private final SubmissionStore store;private final SubmissionService submissions;private final MediaService media;private final ObjectStorage storage;private final ImageNormalizer normalizer;private final TransactionTemplate tx;private final LocalDemoEvents events;private final SubmissionArtifactService artifacts;private final HttpB2bGradingGateway gateway;private final org.botai.back.school.SchoolTaskContent taskContent;
    public record Created(UUID runId,boolean replay) { }
    public UUID operator(Authentication auth){config.requireEnabled();var user=actors.require(auth);config.requireOperator(user.getId());if(user.getRole()!=Role.EXPERT||!origins.operatorActive(user.getId(),false))throw new ApiException(403,"forbidden","Доступ запрещён");return user.getId();}
    public UUID requireRun(UUID actor,UUID run){var rows=store.db().queryForList("SELECT submission_id FROM local_demo_runs WHERE id=?",run);if(rows.isEmpty())throw ApiException.notFound();UUID submission=(UUID)rows.getFirst().get("submission_id");origins.requireOperator(actor,submission,false);return submission;}
    public Created manual(Authentication auth,String key,int number,MultipartFile input,List<MultipartFile> solutions){
        UUID actor=operator(auth);SubmissionService.key(key);if(!Set.of(14,15,16,17,18,19,20).contains(number))throw new ApiException(422,"unsupported_task_number","Это задание пока недоступно");if(input==null||solutions==null||solutions.isEmpty()||solutions.size()>4)throw ApiException.invalid("Нужны условие и от одного до четырёх фото решения");
        byte[] taskBytes=readInput(input);List<byte[]> solutionBytes=solutions.stream().map(this::readInput).toList();String hash=inputHash(number,taskBytes,solutionBytes);byte[] normalizedTask=normalizer.normalize(new ByteArrayInputStream(taskBytes),false).bytes();
        // Persist intent and semantic idempotency before any remote IO or queue admission.
        var prepared=tx.execute(t->{if(!origins.operatorActive(actor,true))throw new ApiException(403,"forbidden","Доступ запрещён");store.db().queryForObject("SELECT id FROM users WHERE id=? FOR UPDATE",UUID.class,actor);var prior=store.db().queryForList("SELECT s.id,s.request_hash,r.id run_id FROM grading_submissions s LEFT JOIN local_demo_runs r ON r.submission_id=s.id WHERE s.user_id=? AND s.idempotency_key=?",actor,key);if(!prior.isEmpty()){var p=prior.getFirst();if(!hash.equals(p.get("request_hash"))||p.get("run_id")==null)throw ApiException.conflict("idempotency_conflict");return new Created((UUID)p.get("run_id"),true);}if(store.db().queryForObject("SELECT count(*) FROM grading_submissions WHERE user_id=? AND created_at>now()-interval '1 hour'",Integer.class,actor)>=100)throw new ApiException(429,"submission_rate_limit","Слишком много проверок");UUID task=UUID.randomUUID(),submission=UUID.randomUUID(),run=UUID.randomUUID();String object="b2b/manual-task/"+UUID.randomUUID();
            store.db().update("INSERT INTO b2b_manual_tasks(id,user_id,task_number,max_score,bucket,object_key,file_name,mime_type,size_bytes,sha256) VALUES(?,?,?,?,?,?,?,'image/jpeg',?,?)",task,actor,number,new int[]{2,3,2,2,3,4,4}[number-14],storage.bucket(),object,"task.jpg",normalizedTask.length,PdfLimits.hash(normalizedTask));
            store.db().update("INSERT INTO grading_submissions(id,user_id,origin,manual_task_id,input_revision,idempotency_key,request_hash,request_id) VALUES(?,?,'local_demo',?,0,?,?,?)",submission,actor,task,key,hash,UUID.randomUUID());store.db().update("INSERT INTO local_demo_runs(id,submission_id,actor_id) VALUES(?,?,?)",run,submission,actor);store.event(submission,"intent_created",actor,Map.of("origin","manual"));return new Created(run,false);});
        if(prepared.replay())return prepared;UUID submission=requireRun(actor,prepared.runId());
        try {
            // Task input normalization is separate from student solution media and its four-image budget.
            var task=store.db().queryForMap("SELECT t.id,t.object_key,t.size_bytes,t.sha256 FROM grading_submissions s JOIN b2b_manual_tasks t ON t.id=s.manual_task_id WHERE s.id=?",submission);
            storage.put(task.get("object_key").toString(),normalizedTask,"image/jpeg");
            for(int i=0;i<solutionBytes.size();i++)media.upload(actor,submission,new ImageFile(solutionBytes.get(i),"solution-"+(i+1)+".jpg",solutions.get(i).getContentType()));
            var caps=gateway.capabilities();gateway.requireManualAvailable();var cap=caps.get(number);if(cap==null||!cap.supported())throw new ApiException(503,"manual_input_unavailable","Распознавание условия временно недоступно");config.requireProvider(cap.providerMode());
            submissions.finalizeSubmission(actor,submission,store.row(submission,actor,false).revision());return prepared;
        }catch(RuntimeException e){tx.executeWithoutResult(t->{var row=store.row(submission,null,true);if(row.status().equals("draft"))store.terminal(row,"failed",e instanceof ApiException a?a.code():"storage_unavailable");});throw e;}
    }
    /** A lost process during preparation never restarts a paid job or leaves an eternal spinner. */
    @org.springframework.scheduling.annotation.Scheduled(fixedDelayString="${app.b2b.preparation-reap-ms:60000}")
    public void reapPreparing(){if(!config.enabled())return;for(var entry:store.db().queryForList("SELECT id FROM grading_submissions WHERE origin='local_demo' AND status='draft' AND updated_at<clock_timestamp()-interval '10 minutes' ORDER BY updated_at LIMIT 100"))tx.executeWithoutResult(t->{var row=store.row((UUID)entry.get("id"),null,true);if(row.status().equals("draft")&&store.db().queryForObject("SELECT updated_at<clock_timestamp()-interval '10 minutes' FROM grading_submissions WHERE id=?",Boolean.class,row.id())){store.terminal(row,"failed","preparation_interrupted");store.db().update("UPDATE stored_objects SET state='delete_pending' WHERE submission_id=? AND state='staged'",row.id());}});}
    private byte[] readInput(MultipartFile file){if(file==null||file.isEmpty())throw ApiException.invalid("Пустое изображение");if(file.getSize()>8388608)throw new ApiException(413,"upload_too_large","Изображение больше 8 МиБ");if(file.getContentType()==null||!Set.of("image/jpeg","image/png").contains(file.getContentType()))throw new ApiException(422,"file_type","Нужен JPEG или PNG");try{byte[] bytes=file.getInputStream().readNBytes(8388609);if(bytes.length>8388608)throw new ApiException(413,"upload_too_large","Изображение больше 8 МиБ");boolean jpg=bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255;boolean png=bytes.length>8&&Arrays.equals(Arrays.copyOf(bytes,8),new byte[]{(byte)137,80,78,71,13,10,26,10});if(!jpg&&!png)throw new ApiException(422,"file_type","Нужен JPEG или PNG");return bytes;}catch(IOException e){throw new ApiException(422,"decode_failed","Не удалось прочитать изображение");}}
    public static String inputHash(int number,byte[] input,List<byte[]> images){try{MessageDigest hash=MessageDigest.getInstance("SHA-256");hash.update("b2b-manual.v1".getBytes(StandardCharsets.UTF_8));hash.update(ByteBuffer.allocate(4).putInt(number).array());List<byte[]> all=new ArrayList<>();all.add(input);all.addAll(images);hash.update(ByteBuffer.allocate(4).putInt(all.size()).array());for(byte[] bytes:all){hash.update(ByteBuffer.allocate(8).putLong(bytes.length).array());hash.update(bytes);}return HexFormat.of().formatHex(hash.digest());}catch(Exception e){throw new IllegalStateException(e);}}
    public Object list(Authentication auth,String origin,String state,Integer requestedLimit,String cursor){UUID actor=operator(auth);if(origin!=null&&!Set.of("school","manual").contains(origin))throw ApiException.invalid("Некорректный источник");if(state!=null&&!Set.of("preparing","queued","running","completed","awaiting_expert","reviewing","returned","failed","unknown","cancelled").contains(state))throw ApiException.invalid("Некорректный статус");int limit=Page.limit(requestedLimit),offset=Page.offset(cursor);List<Object> visible=new ArrayList<>();String scoped="""
            WITH scoped AS (SELECT r.id,r.created_at,CASE WHEN s.origin='local_demo' THEN 'manual' ELSE 'school' END origin,
              CASE WHEN w.status='sent' THEN 'returned' WHEN w.status='draft' THEN 'reviewing' WHEN w.id IS NOT NULL THEN 'awaiting_expert'
               WHEN s.error_code='unknown_after_dispatch' THEN 'unknown' WHEN s.status='draft' THEN 'preparing'
               WHEN s.status IN('graded','rejected','unsupported') THEN 'completed' WHEN s.status='expired' THEN 'failed' ELSE s.status END state
             FROM local_demo_runs r JOIN grading_submissions s ON s.id=r.submission_id LEFT JOIN expert_works w ON w.submission_id=s.id
             WHERE (s.origin='local_demo' AND s.user_id=?) OR (s.origin='school' AND EXISTS(SELECT 1 %s AND a.id=s.school_assignment_id AND es.expert_user_id=?)))
            SELECT id FROM scoped WHERE (?::text IS NULL OR origin=?) AND (?::text IS NULL OR state=?) ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?
            """.formatted(SubmissionOrigins.ACTIVE_SCHOOL);
        for(var r:store.db().queryForList(scoped,actor,actor,origin,origin,state,state,limit+1,offset)){UUID run=(UUID)r.get("id");try{UUID submission=requireRun(actor,run);visible.add(summary(run,submission));}catch(ApiException e){if(e.status()!=404)throw e;}}return Page.of(visible,offset,limit);}
    private Map<String,Object> summary(UUID run,UUID submission){var row=store.db().queryForMap("SELECT s.*,r.created_at run_created_at,t.exam_number,w.id work_id,w.status work_status FROM local_demo_runs r JOIN grading_submissions s ON s.id=r.submission_id JOIN grading_task_snapshots t ON t.submission_id=s.id LEFT JOIN expert_works w ON w.submission_id=s.id WHERE r.id=?",run);String state=state(row);var result=new LinkedHashMap<String,Object>();result.put("id",run);result.put("origin","school".equals(row.get("origin"))?"school":"manual");result.put("submissionId",submission);result.put("assignmentId",row.get("school_assignment_id"));result.put("workId",row.get("work_id"));result.put("taskNumber",row.get("exam_number"));result.put("state",state);result.put("phase",phase(state));result.put("revision",row.get("revision"));result.put("isDemo",row.get("is_demo"));result.put("createdAt",instant(row.get("run_created_at")));result.put("updatedAt",instant(row.get("updated_at")));result.put("errorCode",row.get("error_code"));result.put("failure",Set.of("failed","unknown").contains(state)?events.failure(submission):null);return result;}
    public Object detail(Authentication auth,UUID run){UUID actor=operator(auth),submission=requireRun(actor,run);var result=summary(run,submission);var t=store.db().queryForMap("SELECT * FROM grading_task_snapshots WHERE submission_id=?",submission);Map<String,Object> task=new LinkedHashMap<>();task.put("taskNumber",t.get("exam_number"));task.put("maxScore",t.get("max_score"));task.put("statement",t.get("statement"));task.put("content","school".equals(result.get("origin"))?taskContent.project((UUID)t.get("task_id"),"/api/local-demo/runs/"+run+"/task-media/"):store.json().read(t.get("content").toString()));task.put("referenceAnswer",t.get("reference_answer"));task.put("referenceSolution",t.get("reference_solution"));
        var privateInput=store.db().queryForList("SELECT t.id FROM grading_submissions s JOIN b2b_manual_tasks t ON t.id=s.manual_task_id WHERE s.id=? UNION ALL SELECT a.id FROM grading_submissions s JOIN school_assignments sa ON sa.id=s.school_assignment_id JOIN school_task_assets a ON a.task_id=sa.task_id AND a.school_id=sa.school_id AND a.kind='reference' WHERE s.id=? ORDER BY id LIMIT 1",submission,submission);task.put("inputImage",privateInput.isEmpty()?null:Map.of("id",privateInput.getFirst().get("id"),"previewUrl","/api/local-demo/runs/"+run+"/task-input/"+privateInput.getFirst().get("id")+"/preview"));result.put("task",task);
        List<Object> images=new ArrayList<>();for(var i:store.db().queryForList("SELECT * FROM stored_objects WHERE submission_id=? AND purpose='solution' AND state='ready' ORDER BY ordinal",submission))images.add(imageDto(i,run,true));result.put("images",images);List<Object> documents=new ArrayList<>();var docJson=store.json().read(store.db().queryForObject("SELECT solution_documents_json(?)::text",String.class,submission));for(var d:docJson){var map=new LinkedHashMap<String,Object>();for(var p:d.properties())map.put(p.getKey(),p.getValue());map.put("downloadUrl",d.path("state").asText().equals("ready")?"/api/local-demo/runs/"+run+"/documents/"+d.path("id").asText()+"/download":null);List<Object> pages=new ArrayList<>();for(var p:d.path("pages")){Map<String,Object> page=new LinkedHashMap<>();for(var e:p.properties())page.put(e.getKey(),e.getValue());page.put("previewUrl","/api/local-demo/runs/"+run+"/images/"+p.path("id").asText()+"/preview");pages.add(page);}map.put("pages",pages);documents.add(map);}result.put("documents",documents);
        var ai=store.db().queryForList("SELECT feedback::text FROM grading_results WHERE submission_id=?",submission);JsonNode canonical=ai.isEmpty()?null:store.json().read((String)ai.getFirst().get("feedback"));result.put("aiResult",canonical);List<Object> publicArtifacts=new ArrayList<>();if(canonical!=null)for(String kind:List.of("ocr","analysis","grading")){var document=canonical.get(kind);if(document!=null&&!document.isNull()){Map<String,Object> a=new LinkedHashMap<>();a.put("id",UUID.nameUUIDFromBytes((run+":"+kind).getBytes(StandardCharsets.UTF_8)));a.put("kind",kind);a.put("state","available");a.put("document",document);a.put("previewUrl",null);publicArtifacts.add(a);}}result.put("artifacts",publicArtifacts);List<Object> crops=new ArrayList<>();for(var a:store.db().queryForList("SELECT id,width,height FROM submission_artifacts WHERE submission_id=? AND state='ready'",submission))crops.add(SubmissionArtifactService.dto((UUID)a.get("id"),"/api/local-demo/runs/"+run+"/image-artifacts/"+a.get("id")+"/preview",((Number)a.get("width")).intValue(),((Number)a.get("height")).intValue()));result.put("imageArtifacts",crops);result.put("lastEventSeq",events.lastSeq(submission));result.put("observer",events.observerStatus(submission));origins.requireOperator(actor,submission,false);return result;
    }
    private Map<String,Object> imageDto(Map<String,Object> i,UUID run,boolean status){Map<String,Object> dto=new LinkedHashMap<>();dto.put("id",i.get("id"));dto.put("fileName",i.get("file_name"));dto.put("mimeType",i.get("mime_type"));dto.put("sizeBytes",i.get("size_bytes"));dto.put("previewUrl","/api/local-demo/runs/"+run+"/images/"+i.get("id")+"/preview");dto.put("sourceDocumentId",i.get("source_document_id"));dto.put("pageNumber",i.get("page_number"));if(status)dto.put("status","ready");return dto;}
    public Object events(Authentication auth,UUID run,long after,int limit){UUID actor=operator(auth),submission=requireRun(actor,run);Object page=events.page(submission,after,limit);origins.requireOperator(actor,submission,false);return page;}
    public MediaService.Content image(Authentication auth,UUID run,UUID image,boolean task){UUID actor=operator(auth),submission=requireRun(actor,run);var rows=task?store.db().queryForList("SELECT t.object_key,t.sha256,t.size_bytes,t.mime_type FROM grading_submissions s JOIN b2b_manual_tasks t ON t.id=s.manual_task_id WHERE s.id=? AND t.id=? UNION ALL SELECT a.object_key,a.sha256,a.size_bytes,a.mime_type FROM grading_submissions s JOIN school_assignments sa ON sa.id=s.school_assignment_id JOIN school_task_assets a ON a.task_id=sa.task_id AND a.school_id=sa.school_id WHERE s.id=? AND a.id=?",submission,image,submission,image):store.db().queryForList("SELECT object_key,sha256,size_bytes,mime_type FROM stored_objects WHERE submission_id=? AND id=? AND purpose='solution' AND state='ready'",submission,image);if(rows.isEmpty())throw ApiException.notFound();byte[] bytes=read(rows.getFirst(),8388608);origins.requireOperator(actor,submission,false);return new MediaService.Content(bytes,rows.getFirst().get("mime_type").toString());}
    public MediaService.Content artifact(Authentication auth,UUID run,UUID id){UUID actor=operator(auth);return artifacts.operatorPreview(actor,requireRun(actor,run),id);}
    public SolutionDocumentService.Original document(Authentication auth,UUID run,UUID id){UUID actor=operator(auth),submission=requireRun(actor,run);var rows=store.db().queryForList("SELECT object_key,sha256,size_bytes,file_name FROM solution_documents WHERE submission_id=? AND id=? AND state='ready'",submission,id);if(rows.isEmpty())throw ApiException.notFound();var row=rows.getFirst();byte[] bytes=read(row,PdfLimits.INPUT_BYTES);origins.requireOperator(actor,submission,false);return new SolutionDocumentService.Original(bytes,row.get("file_name").toString());}
    private byte[] read(Map<String,Object> row,long max){try{byte[] bytes=storage.get(row.get("object_key").toString(),max);if(bytes.length!=((Number)row.get("size_bytes")).longValue()||!PdfLimits.hash(bytes).equals(row.get("sha256")))throw new IllegalStateException();return bytes;}catch(Exception e){throw new ApiException(503,"storage_unavailable","Файл временно недоступен");}}
    private static String instant(Object o){return o==null?null:o instanceof java.sql.Timestamp t?t.toInstant().toString():o instanceof java.time.OffsetDateTime t?t.toInstant().toString():o.toString();}
    private static String state(Map<String,Object> row){String work=(String)row.get("work_status");if("sent".equals(work))return"returned";if("draft".equals(work))return"reviewing";if(row.get("work_id")!=null)return"awaiting_expert";if("unknown_after_dispatch".equals(row.get("error_code")))return"unknown";return switch(row.get("status").toString()){case "draft"->"preparing";case "graded","rejected","unsupported"->"completed";case "expired"->"failed";default->row.get("status").toString();};}
    private static String phase(String state){return switch(state){case "preparing"->"input_received";case "running"->"ai_running";case "completed"->"ai_completed";case "awaiting_expert"->"expert_queued";case "reviewing"->"expert_draft";case "returned"->"expert_sent";default->state;};}
    private record ImageFile(byte[] bytes,String name,String type) implements MultipartFile {public String getName(){return"file";}public String getOriginalFilename(){return name;}public String getContentType(){return type;}public boolean isEmpty(){return bytes.length==0;}public long getSize(){return bytes.length;}public byte[] getBytes(){return bytes;}public InputStream getInputStream(){return new ByteArrayInputStream(bytes);}public void transferTo(File f)throws IOException{try(var out=new FileOutputStream(f)){out.write(bytes);}}}
}
